def rewrite_coding_prompt(source_prompt, source_language_hint=None, request_context=None, client_request_id=None, variants=None, timeout_ms=None, **_extra):
    import json, os, datetime, time, uuid, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0457000" if __import__("os").path.isdir("./environment_mix/0457000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _audit_append(audits, event_type, api_key_id=None, rewrite_request_id=None, ip_address=None, user_agent=None, details=None):
        ts = _now()
        audits.append({
            "id": _gen_id("aud"),
            "event_type": event_type,
            "api_key_id": api_key_id,
            "rewrite_request_id": rewrite_request_id,
            "ip_address": ip_address,
            "user_agent": user_agent,
            "details": details if isinstance(details, (dict, list)) or details is None else {"details": str(details)},
            "created_at": ts,
            "updated_at": ts,
        })

    def _fingerprint(raw):
        if not isinstance(raw, str) or raw == "":
            return None
        b = raw.encode("utf-8")
        return hashlib.sha256(b).hexdigest()

    def _resolve_api_key_any():
        # Ambient auth: pick a usable active key if any exist.
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                return k, keys
        return None, keys

    def _reset_month_window_if_needed(krow, now_dt):
        # If month_window_start is missing or older than current UTC month, reset usage.
        mws = _parse_rfc3339(krow.get("month_window_start")) if isinstance(krow, dict) else None
        if mws is None:
            krow["month_window_start"] = now_dt.isoformat()
            krow["monthly_requests_used"] = int(krow.get("monthly_requests_used") or 0)
            return True
        if mws.tzinfo is None:
            mws = mws.replace(tzinfo=datetime.timezone.utc)
        if (mws.year, mws.month) != (now_dt.year, now_dt.month):
            krow["month_window_start"] = now_dt.isoformat()
            krow["monthly_requests_used"] = 0
            return True
        return False

    def _minute_bucket(ts_dt):
        if ts_dt.tzinfo is None:
            ts_dt = ts_dt.replace(tzinfo=datetime.timezone.utc)
        return ts_dt.replace(second=0, microsecond=0)

    def _count_recent_requests(audits, api_key_id, ip_address, now_dt):
        # Count REQUEST_RECEIVED in the current minute bucket for api_key_id or ip.
        bucket = _minute_bucket(now_dt)
        n = 0
        for e in audits:
            if not isinstance(e, dict):
                continue
            if e.get("event_type") != "REQUEST_RECEIVED":
                continue
            created = _parse_rfc3339(e.get("created_at"))
            if created is None:
                continue
            if created.tzinfo is None:
                created = created.replace(tzinfo=datetime.timezone.utc)
            if _minute_bucket(created) != bucket:
                continue
            if api_key_id is not None:
                if e.get("api_key_id") == api_key_id:
                    n += 1
            else:
                if ip_address is not None and e.get("ip_address") == ip_address:
                    n += 1
        return n

    def _sanitize_int(v):
        if v is None:
            return None
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        return None

    # Validate inputs
    if not isinstance(source_prompt, str) or source_prompt.strip() == "":
        return _err("VALIDATION_ERROR", "source_prompt must be a non-empty string")
    if source_language_hint is not None and not isinstance(source_language_hint, str):
        return _err("VALIDATION_ERROR", "source_language_hint must be a string")
    if request_context is not None and not isinstance(request_context, dict):
        return _err("VALIDATION_ERROR", "request_context must be an object")
    if client_request_id is not None and not isinstance(client_request_id, str):
        return _err("VALIDATION_ERROR", "client_request_id must be a string")
    v_int = _sanitize_int(variants)
    if variants is None:
        v_int = 1
    if v_int is None or v_int < 1 or v_int > 10:
        return _err("VALIDATION_ERROR", "variants must be an integer between 1 and 10")
    t_int = _sanitize_int(timeout_ms)
    if timeout_ms is not None and (t_int is None or t_int < 0 or t_int > 120000):
        return _err("VALIDATION_ERROR", "timeout_ms must be an integer between 0 and 120000")

    t0 = time.time()

    # Load stores
    audits = _load("audit_events.json")
    requests = _load("rewrite_requests.json")
    outputs = _load("rewrite_outputs.json")
    runs = _load("model_runs.json")

    # Ambient context for ip/user-agent (may be passed by gateway via _extra)
    ip_address = _extra.get("ip_address")
    user_agent = _extra.get("user_agent")
    if ip_address is not None and not isinstance(ip_address, str):
        ip_address = None
    if user_agent is not None and not isinstance(user_agent, str):
        user_agent = None

    # Resolve auth context: pick any active key if available; otherwise unauth/internal (api_key_id null).
    api_key_row, all_keys = _resolve_api_key_any()
    api_key_id = api_key_row.get("id") if api_key_row else None

    # Idempotency: if client_request_id present, return existing request for this api_key_id (or null key)
    if client_request_id is not None:
        for rr in requests:
            if not isinstance(rr, dict):
                continue
            if rr.get("client_request_id") == client_request_id and rr.get("api_key_id") == api_key_id:
                # Record call as received (still counts for rate limiting in real life; apply before return)
                now_dt = datetime.datetime.now(datetime.timezone.utc)
                _audit_append(audits, "REQUEST_RECEIVED", api_key_id=api_key_id, rewrite_request_id=rr.get("id"),
                              ip_address=ip_address, user_agent=user_agent,
                              details={"idempotent_replay": True})
                # Enforce rate limit even for replay (service typically would; keep consistent with counters)
                if api_key_row:
                    limit = api_key_row.get("requests_per_minute_limit")
                    if not isinstance(limit, int) or limit < 1:
                        limit = 60
                    recent = _count_recent_requests(audits, api_key_id, ip_address, now_dt)
                    if recent > limit:
                        _audit_append(audits, "RATE_LIMIT_BLOCK", api_key_id=api_key_id, rewrite_request_id=rr.get("id"),
                                      ip_address=ip_address, user_agent=user_agent,
                                      details={"requests_per_minute_limit": limit, "recent_minute_requests": recent})
                        _save("audit_events.json", audits)
                        return _err("RATE_LIMIT", "Rate limit exceeded")
                else:
                    # unauth: apply a conservative per-IP rate limit
                    limit = 30
                    recent = _count_recent_requests(audits, None, ip_address, now_dt)
                    if recent > limit:
                        _audit_append(audits, "RATE_LIMIT_BLOCK", api_key_id=None, rewrite_request_id=rr.get("id"),
                                      ip_address=ip_address, user_agent=user_agent,
                                      details={"requests_per_minute_limit": limit, "recent_minute_requests": recent})
                        _save("audit_events.json", audits)
                        return _err("RATE_LIMIT", "Rate limit exceeded")

                # Persist audit
                _save("audit_events.json", audits)

                # Assemble response
                rr_id = rr.get("id")
                rr_outs = [o for o in outputs if isinstance(o, dict) and o.get("rewrite_request_id") == rr_id and o.get("status") != "deleted"]
                rr_runs = [r for r in runs if isinstance(r, dict) and r.get("rewrite_request_id") == rr_id]
                latency_ms = int((time.time() - t0) * 1000)
                return {
                    "rewrite_request": rr,
                    "outputs": sorted(rr_outs, key=lambda x: x.get("variant_index", 0)),
                    "model_runs": sorted(rr_runs, key=lambda x: x.get("started_at") or ""),
                    "meta": {"idempotent": True, "latency_ms": latency_ms}
                }

    now = _now()
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    # Audit: request received (must happen for every call)
    tmp_req_id = _gen_id("rwr")  # use as placeholder in audit; later replace with real id (same)
    _audit_append(audits, "REQUEST_RECEIVED", api_key_id=api_key_id, rewrite_request_id=tmp_req_id,
                  ip_address=ip_address, user_agent=user_agent,
                  details={"variants": v_int, "timeout_ms": t_int})

    # Enforce API key status if present
    if api_key_row and api_key_row.get("status") != "active":
        _save("audit_events.json", audits)
        return _err("UNAUTHORIZED", "API key is not active")

    # Enforce monthly quota (if authenticated with a key)
    keys_dirty = False
    if api_key_row:
        keys_dirty |= _reset_month_window_if_needed(api_key_row, now_dt)
        limit = api_key_row.get("monthly_requests_limit")
        used = api_key_row.get("monthly_requests_used")
        if not isinstance(used, int) or used < 0:
            used = 0
            api_key_row["monthly_requests_used"] = 0
            keys_dirty = True
        if limit is not None and (not isinstance(limit, int) or limit < 1):
            _save("audit_events.json", audits)
            return _err("VALIDATION_ERROR", "Stored api key monthly_requests_limit is invalid")
        if limit is not None and used >= limit:
            # Must create rewrite_request row as failed with QUOTA_EXCEEDED
            rr = {
                "id": tmp_req_id,
                "api_key_id": api_key_id,
                "status": "failed",
                "source_prompt": source_prompt,
                "source_language_hint": source_language_hint,
                "request_context": request_context,
                "client_request_id": client_request_id,
                "error_code": "QUOTA_EXCEEDED",
                "error_message": "Monthly request quota exceeded",
                "queued_at": None,
                "started_at": None,
                "finished_at": now,
                "created_at": now,
                "updated_at": now,
            }
            requests.append(rr)
            _audit_append(audits, "QUOTA_BLOCK", api_key_id=api_key_id, rewrite_request_id=tmp_req_id,
                          ip_address=ip_address, user_agent=user_agent,
                          details={"monthly_requests_limit": limit, "monthly_requests_used": used})
            _audit_append(audits, "REQUEST_FAILED", api_key_id=api_key_id, rewrite_request_id=tmp_req_id,
                          ip_address=ip_address, user_agent=user_agent,
                          details={"error_code": "QUOTA_EXCEEDED"})
            _save("rewrite_requests.json", requests)
            _save("audit_events.json", audits)
            if keys_dirty:
                # update key updated_at even though usage did not increment
                api_key_row["updated_at"] = now
                _save("api_keys.json", all_keys)
            return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded")

    # Enforce per-minute rate limit (per key or per IP when unauth)
    if api_key_row:
        limit = api_key_row.get("requests_per_minute_limit")
        if not isinstance(limit, int) or limit < 1:
            _save("audit_events.json", audits)
            return _err("VALIDATION_ERROR", "Stored api key requests_per_minute_limit is invalid")
        recent = _count_recent_requests(audits, api_key_id, ip_address, now_dt)
        if recent > limit:
            # Must not start model run
            rr = {
                "id": tmp_req_id,
                "api_key_id": api_key_id,
                "status": "failed",
                "source_prompt": source_prompt,
                "source_language_hint": source_language_hint,
                "request_context": request_context,
                "client_request_id": client_request_id,
                "error_code": "RATE_LIMITED",
                "error_message": "Rate limit exceeded",
                "queued_at": None,
                "started_at": None,
                "finished_at": now,
                "created_at": now,
                "updated_at": now,
            }
            requests.append(rr)
            _audit_append(audits, "RATE_LIMIT_BLOCK", api_key_id=api_key_id, rewrite_request_id=tmp_req_id,
                          ip_address=ip_address, user_agent=user_agent,
                          details={"requests_per_minute_limit": limit, "recent_minute_requests": recent})
            _audit_append(audits, "REQUEST_FAILED", api_key_id=api_key_id, rewrite_request_id=tmp_req_id,
                          ip_address=ip_address, user_agent=user_agent,
                          details={"error_code": "RATE_LIMITED"})
            _save("rewrite_requests.json", requests)
            _save("audit_events.json", audits)
            if keys_dirty:
                api_key_row["updated_at"] = now
                _save("api_keys.json", all_keys)
            return _err("RATE_LIMIT", "Rate limit exceeded")
    else:
        # Per-IP rate limit for unauth/internal calls
        limit = 30
        recent = _count_recent_requests(audits, None, ip_address, now_dt)
        if recent > limit:
            rr = {
                "id": tmp_req_id,
                "api_key_id": None,
                "status": "failed",
                "source_prompt": source_prompt,
                "source_language_hint": source_language_hint,
                "request_context": request_context,
                "client_request_id": client_request_id,
                "error_code": "RATE_LIMITED",
                "error_message": "Rate limit exceeded",
                "queued_at": None,
                "started_at": None,
                "finished_at": now,
                "created_at": now,
                "updated_at": now,
            }
            requests.append(rr)
            _audit_append(audits, "RATE_LIMIT_BLOCK", api_key_id=None, rewrite_request_id=tmp_req_id,
                          ip_address=ip_address, user_agent=user_agent,
                          details={"requests_per_minute_limit": limit, "recent_minute_requests": recent})
            _audit_append(audits, "REQUEST_FAILED", api_key_id=None, rewrite_request_id=tmp_req_id,
                          ip_address=ip_address, user_agent=user_agent,
                          details={"error_code": "RATE_LIMITED"})
            _save("rewrite_requests.json", requests)
            _save("audit_events.json", audits)
            return _err("RATE_LIMIT", "Rate limit exceeded")

    # Create rewrite request (queued)
    rr = {
        "id": tmp_req_id,
        "api_key_id": api_key_id,
        "status": "queued",
        "source_prompt": source_prompt,
        "source_language_hint": source_language_hint,
        "request_context": request_context,
        "client_request_id": client_request_id,
        "error_code": None,
        "error_message": None,
        "queued_at": now,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    requests.append(rr)
    _audit_append(audits, "REQUEST_QUEUED", api_key_id=api_key_id, rewrite_request_id=tmp_req_id,
                  ip_address=ip_address, user_agent=user_agent, details=None)

    # Synchronous execution: queued -> running (allowed)
    rr["status"] = "running"
    rr["started_at"] = _now()
    rr["updated_at"] = rr["started_at"]
    _audit_append(audits, "REQUEST_STARTED", api_key_id=api_key_id, rewrite_request_id=tmp_req_id,
                  ip_address=ip_address, user_agent=user_agent, details=None)

    # Start model run
    run_started = _now()
    run_id = _gen_id("run")
    run = {
        "id": run_id,
        "rewrite_request_id": tmp_req_id,
        "status": "started",
        "provider": "local",
        "model": "prompt-rewrite-v1",
        "prompt_template_version": "v1",
        "input_tokens": None,
        "output_tokens": None,
        "total_tokens": None,
        "latency_ms": None,
        "cost_usd": None,
        "error_message": None,
        "started_at": run_started,
        "finished_at": None,
        "created_at": run_started,
        "updated_at": run_started,
    }
    runs.append(run)

    # Generate variants (deterministic-ish based on content)
    def _make_variant(i):
        fp = _fingerprint(source_prompt) or ""
        lang = (source_language_hint or "").strip()
        header = "Rewrite the following coding prompt to be clear, complete, and testable."
        if lang:
            header += f" Target ecosystem/language: {lang}."
        if i == 0:
            style = "Produce a structured prompt with explicit requirements, constraints, and acceptance criteria."
        elif i == 1:
            style = "Produce a concise prompt optimized for implementation speed; include edge cases."
        else:
            style = "Produce a prompt optimized for correctness; include validation steps and non-functional requirements."
        ctx_note = ""
        if isinstance(request_context, dict) and request_context:
            ctx_note = f"\nContext (for reference): {json.dumps(request_context, ensure_ascii=False, sort_keys=True)[:2000]}"
        rewritten = (
            f"{header}\n\n"
            f"{style}\n\n"
            f"Original prompt:\n{source_prompt.strip()}\n"
            f"{ctx_note}\n\n"
            f"Server trace: fp={fp[:12]} variant={i}"
        )
        sections = {
            "requirements": [
                "State the goal and expected deliverables.",
                "List inputs/outputs and any formatting requirements."
            ],
            "constraints": [
                "Include performance/complexity constraints if relevant.",
                "Specify allowed libraries/tools and forbidden approaches if any."
            ],
            "acceptance_criteria": [
                "Define what constitutes a correct solution.",
                "Include example(s) and edge cases."
            ],
            "edge_cases": [
                "Null/empty inputs",
                "Large inputs",
                "Invalid inputs handling"
            ],
        }
        return rewritten, sections

    # Write outputs with unique variant_index
    existing_variant_indexes = set()
    for o in outputs:
        if isinstance(o, dict) and o.get("rewrite_request_id") == tmp_req_id:
            vi = o.get("variant_index")
            if isinstance(vi, int):
                existing_variant_indexes.add(vi)

    created_outputs = []
    for i in range(v_int):
        if i in existing_variant_indexes:
            continue
        rewritten, sections = _make_variant(i)
        ts = _now()
        out = {
            "id": _gen_id("out"),
            "rewrite_request_id": tmp_req_id,
            "variant_index": i,
            "status": "generated",
            "rewritten_prompt": rewritten,
            "structured_sections": sections,
            "quality_score": None,
            "created_at": ts,
            "updated_at": ts,
        }
        outputs.append(out)
        created_outputs.append(out)

    # Must have at least one generated output to succeed
    if not created_outputs:
        # Fail the run and request
        fin = _now()
        run["status"] = "failed"
        run["error_message"] = "No outputs generated"
        run["finished_at"] = fin
        run["updated_at"] = fin

        rr["status"] = "failed"
        rr["error_code"] = "INTERNAL_ERROR"
        rr["error_message"] = "No outputs generated"
        rr["finished_at"] = fin
        rr["updated_at"] = fin
        _audit_append(audits, "REQUEST_FAILED", api_key_id=api_key_id, rewrite_request_id=tmp_req_id,
                      ip_address=ip_address, user_agent=user_agent, details={"error_code": "INTERNAL_ERROR"})
        # Persist everything
        _save("rewrite_requests.json", requests)
        _save("model_runs.json", runs)
        _save("rewrite_outputs.json", outputs)
        _save("audit_events.json", audits)
        return _err("CONFLICT", "Rewrite request could not be completed")

    # Succeed run and request
    fin = _now()
    run["status"] = "succeeded"
    run["finished_at"] = fin
    run["updated_at"] = fin
    run["latency_ms"] = max(0, int((time.time() - t0) * 1000))

    rr["status"] = "succeeded"
    rr["finished_at"] = fin
    rr["updated_at"] = fin
    _audit_append(audits, "REQUEST_SUCCEEDED", api_key_id=api_key_id, rewrite_request_id=tmp_req_id,
                  ip_address=ip_address, user_agent=user_agent, details={"variants_generated": len(created_outputs)})

    # Update api_key usage on success path (counts requests)
    if api_key_row:
        api_key_row["monthly_requests_used"] = int(api_key_row.get("monthly_requests_used") or 0) + 1
        api_key_row["last_used_at"] = fin
        api_key_row["updated_at"] = fin
        keys_dirty = True

    # Persist all
    _save("rewrite_requests.json", requests)
    _save("rewrite_outputs.json", outputs)
    _save("model_runs.json", runs)
    _save("audit_events.json", audits)
    if keys_dirty and api_key_row:
        _save("api_keys.json", all_keys)

    latency_ms = int((time.time() - t0) * 1000)
    # timeout_ms behavior: since this is synchronous, if timeout_ms is 0 return current job status (running)
    if t_int is not None and t_int == 0:
        # Return running state without modifying stored succeeded outcome (but still accurate: job is already done).
        pass

    rr_id = rr["id"]
    rr_outs = [o for o in outputs if isinstance(o, dict) and o.get("rewrite_request_id") == rr_id and o.get("status") != "deleted"]
    rr_runs = [r for r in runs if isinstance(r, dict) and r.get("rewrite_request_id") == rr_id]
    return {
        "rewrite_request": rr,
        "outputs": sorted(rr_outs, key=lambda x: x.get("variant_index", 0)),
        "model_runs": sorted(rr_runs, key=lambda x: x.get("started_at") or ""),
        "meta": {"latency_ms": latency_ms}
    }

def get_current_identity(api_key, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0457000" if __import__("os").path.isdir("./environment_mix/0457000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_s():
        return _now().isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _minute_bucket(ts_dt):
        if ts_dt.tzinfo is None:
            ts_dt = ts_dt.replace(tzinfo=datetime.timezone.utc)
        return ts_dt.replace(second=0, microsecond=0)

    def _count_recent_requests(audits, api_key_id, now_dt):
        bucket = _minute_bucket(now_dt)
        n = 0
        for e in audits:
            if not isinstance(e, dict):
                continue
            if e.get("event_type") != "REQUEST_RECEIVED":
                continue
            if e.get("api_key_id") != api_key_id:
                continue
            created = _parse_rfc3339(e.get("created_at"))
            if created is None:
                continue
            if created.tzinfo is None:
                created = created.replace(tzinfo=datetime.timezone.utc)
            if _minute_bucket(created) == bucket:
                n += 1
        return n

    def _audit_append(audits, event_type, api_key_id=None, rewrite_request_id=None, ip_address=None, user_agent=None, details=None):
        import uuid
        ts = _now_s()
        audits.append({
            "id": f"aud_{uuid.uuid4().hex}",
            "event_type": event_type,
            "api_key_id": api_key_id,
            "rewrite_request_id": rewrite_request_id,
            "ip_address": ip_address,
            "user_agent": user_agent,
            "details": details if isinstance(details, (dict, list)) or details is None else {"details": str(details)},
            "created_at": ts,
            "updated_at": ts,
        })

    # Validate
    if not isinstance(api_key, str) or api_key.strip() == "":
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    t0 = time.time()
    keys = _load("api_keys.json")
    audits = _load("audit_events.json")

    # Authenticate by matching id OR key_hash (client-visible value might be stored directly)
    krow = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            krow = k
            break
    if krow is None:
        # Record attempt as request received (no api_key_id)
        _audit_append(audits, "REQUEST_RECEIVED", api_key_id=None, rewrite_request_id=None,
                      ip_address=_extra.get("ip_address") if isinstance(_extra.get("ip_address"), str) else None,
                      user_agent=_extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None,
                      details={"endpoint": "get_current_identity", "auth": "invalid"})
        _save("audit_events.json", audits)
        return _err("UNAUTHORIZED", "Invalid API key")

    if krow.get("status") != "active":
        _audit_append(audits, "REQUEST_RECEIVED", api_key_id=krow.get("id"), rewrite_request_id=None,
                      ip_address=_extra.get("ip_address") if isinstance(_extra.get("ip_address"), str) else None,
                      user_agent=_extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None,
                      details={"endpoint": "get_current_identity", "auth": "inactive"})
        _save("audit_events.json", audits)
        return _err("UNAUTHORIZED", "API key is not active")

    # Record call
    _audit_append(audits, "REQUEST_RECEIVED", api_key_id=krow.get("id"), rewrite_request_id=None,
                  ip_address=_extra.get("ip_address") if isinstance(_extra.get("ip_address"), str) else None,
                  user_agent=_extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None,
                  details={"endpoint": "get_current_identity"})
    _save("audit_events.json", audits)

    now_dt = _now()
    recent = _count_recent_requests(audits, krow.get("id"), now_dt)

    identity = {
        "api_key_id": krow.get("id"),
        "label": krow.get("label"),
        "status": krow.get("status"),
        "scopes": ["rewrite:read", "rewrite:write"],
        "rate_limit": {
            "requests_per_minute_limit": krow.get("requests_per_minute_limit"),
            "requests_in_current_minute": recent,
        },
        "quota": {
            "monthly_requests_limit": krow.get("monthly_requests_limit"),
            "monthly_requests_used": krow.get("monthly_requests_used"),
            "month_window_start": krow.get("month_window_start"),
        },
        "timestamps": {
            "last_used_at": krow.get("last_used_at"),
            "created_at": krow.get("created_at"),
            "updated_at": krow.get("updated_at"),
        },
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }
    return {"identity": identity}

def list_rewrite_requests(api_key, status=None, client_request_id=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0457000" if __import__("os").path.isdir("./environment_mix/0457000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_s():
        return _now().isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit_append(audits, event_type, api_key_id=None, rewrite_request_id=None, ip_address=None, user_agent=None, details=None):
        import uuid
        ts = _now_s()
        audits.append({
            "id": f"aud_{uuid.uuid4().hex}",
            "event_type": event_type,
            "api_key_id": api_key_id,
            "rewrite_request_id": rewrite_request_id,
            "ip_address": ip_address,
            "user_agent": user_agent,
            "details": details if isinstance(details, (dict, list)) or details is None else {"details": str(details)},
            "created_at": ts,
            "updated_at": ts,
        })

    def _decode_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or tok.strip() == "":
            return None
        try:
            raw = base64.urlsafe_b64decode(tok.encode("utf-8") + b"==")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_token(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate
    if not isinstance(api_key, str) or api_key.strip() == "":
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ["queued", "running", "succeeded", "failed", "cancelled"]:
            return _err("VALIDATION_ERROR", "status must be one of queued,running,succeeded,failed,cancelled")
    if client_request_id is not None and not isinstance(client_request_id, str):
        return _err("VALIDATION_ERROR", "client_request_id must be a string")
    ca = _parse_rfc3339(created_after)
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 timestamp string")
    cb = _parse_rfc3339(created_before)
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 timestamp string")
    if page_size is None:
        page_size = 50
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")
    if page_token is not None and not isinstance(page_token, str):
        return _err("VALIDATION_ERROR", "page_token must be a string")

    t0 = time.time()
    keys = _load("api_keys.json")
    requests = _load("rewrite_requests.json")
    audits = _load("audit_events.json")

    # Authenticate by id OR key_hash
    krow = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            krow = k
            break
    if krow is None or krow.get("status") != "active":
        _audit_append(audits, "REQUEST_RECEIVED", api_key_id=(krow.get("id") if krow else None), rewrite_request_id=None,
                      ip_address=_extra.get("ip_address") if isinstance(_extra.get("ip_address"), str) else None,
                      user_agent=_extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None,
                      details={"endpoint": "list_rewrite_requests", "auth": "failed"})
        _save("audit_events.json", audits)
        return _err("UNAUTHORIZED", "Unauthorized")

    # Record call
    _audit_append(audits, "REQUEST_RECEIVED", api_key_id=krow.get("id"), rewrite_request_id=None,
                  ip_address=_extra.get("ip_address") if isinstance(_extra.get("ip_address"), str) else None,
                  user_agent=_extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None,
                  details={"endpoint": "list_rewrite_requests"})
    _save("audit_events.json", audits)

    # Filter scoped to this key
    rows = []
    for rr in requests:
        if not isinstance(rr, dict):
            continue
        if rr.get("api_key_id") != krow.get("id"):
            continue
        if status is not None and rr.get("status") != status:
            continue
        if client_request_id is not None and rr.get("client_request_id") != client_request_id:
            continue
        created = _parse_rfc3339(rr.get("created_at"))
        if created is None:
            # if missing, include unless a time filter is set
            if ca is not None or cb is not None:
                continue
        else:
            if created.tzinfo is None:
                created = created.replace(tzinfo=datetime.timezone.utc)
            if ca is not None:
                if ca.tzinfo is None:
                    ca = ca.replace(tzinfo=datetime.timezone.utc)
                if created <= ca:
                    continue
            if cb is not None:
                if cb.tzinfo is None:
                    cb = cb.replace(tzinfo=datetime.timezone.utc)
                if created >= cb:
                    continue
        rows.append(rr)

    # Sort by created_at desc, tie-break by id desc
    def _sort_key(rr):
        c = rr.get("created_at") or ""
        return (c, rr.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    # Pagination
    cursor = _decode_token(page_token)
    start = 0
    if cursor is not None:
        if cursor.get("v") != 1 or cursor.get("api_key_id") != krow.get("id"):
            return _err("VALIDATION_ERROR", "Invalid page_token")
        last_created = cursor.get("last_created_at")
        last_id = cursor.get("last_id")
        # find first item strictly after the cursor in the sorted list
        for i, rr in enumerate(rows):
            if (rr.get("created_at") or "") < (last_created or ""):
                start = i
                break
            if (rr.get("created_at") or "") == (last_created or "") and (rr.get("id") or "") < (last_id or ""):
                start = i
                break
        else:
            start = len(rows)

    page = rows[start:start + page_size]
    has_more = (start + page_size) < len(rows)
    next_token = None
    if has_more and page:
        last = page[-1]
        next_token = _encode_token({
            "v": 1,
            "api_key_id": krow.get("id"),
            "last_created_at": last.get("created_at"),
            "last_id": last.get("id"),
        })

    return {
        "rewrite_requests": page,
        "meta": {
            "total": len(rows),
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_token,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

def get_rewrite_request(api_key, rewrite_request_id, include_outputs=None, include_model_runs=None, **_extra):
