            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _audit_append(audits, event_type, api_key_id=None, rewrite_request_id=None, ip_address=None, user_agent=None, details=None):
        import uuid
        ts = _now()
        audits.append({
            "id": f"aud_{uuid.uuid4().hex}",
            "event_type": event_type,
            "api_key_id": api_key_id,
