            "user_agent": user_agent,
            "details": details if isinstance(details, (dict, list)) or details is None else {"details": str(details)},
            "created_at": ts,
            "updated_at": ts,
        })

    # Validate
    if not isinstance(api_key, str) or api_key.strip() == "":
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(rewrite_request_id, str) or rewrite_request_id.strip() == "":
        return _err("VALIDATION_ERROR", "rewrite_request_id must be a non-empty string")
    if include_outputs is None:
        include_outputs = False
    if include_model_runs is None:
        include_model_runs = False
    if not isinstance(include_outputs, bool):
        return _err("VALIDATION_ERROR", "include_outputs must be a boolean")
    if not isinstance(include_model_runs, bool):
        return _err("VALIDATION_ERROR", "include_model_runs must be a boolean")

    t0 = time.time()
    keys = _load("api_keys.json")
    requests = _load("rewrite_requests.json")
    outputs = _load("rewrite_outputs.json")
    runs = _load("model_runs.json")
    audits = _load("audit_events.json")

    # Authenticate by id OR key_hash
    krow = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            krow = k
            break
    if krow is None or krow.get("status") != "active":
        _audit_append(audits, "REQUEST_RECEIVED", api_key_id=(krow.get("id") if krow else None), rewrite_request_id=rewrite_request_id,
                      ip_address=_extra.get("ip_address") if isinstance(_extra.get("ip_address"), str) else None,
                      user_agent=_extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None,
                      details={"endpoint": "get_rewrite_request", "auth": "failed"})
        _save("audit_events.json", audits)
        return _err("UNAUTHORIZED", "Unauthorized")

    # Record call
    _audit_append(audits, "REQUEST_RECEIVED", api_key_id=krow.get("id"), rewrite_request_id=rewrite_request_id,
                  ip_address=_extra.get("ip_address") if isinstance(_extra.get("ip_address"), str) else None,
                  user_agent=_extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None,
                  details={"endpoint": "get_rewrite_request", "include_outputs": include_outputs, "include_model_runs": include_model_runs})
    _save("audit_events.json", audits)

    rr = None
    for r in requests:
        if isinstance(r, dict) and r.get("id") == rewrite_request_id:
            rr = r
            break
    if rr is None:
        return _err("NOT_FOUND", "Rewrite request not found")

    if rr.get("api_key_id") != krow.get("id"):
        return _err("UNAUTHORIZED", "Not authorized to access this rewrite request")

    resp = {"rewrite_request": rr, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}
    if include_outputs:
        rr_outs = [o for o in outputs if isinstance(o, dict) and o.get("rewrite_request_id") == rewrite_request_id and o.get("status") != "deleted"]
        rr_outs.sort(key=lambda x: x.get("variant_index", 0))
        resp["outputs"] = rr_outs
    if include_model_runs:
        rr_runs = [m for m in runs if isinstance(m, dict) and m.get("rewrite_request_id") == rewrite_request_id]
        rr_runs.sort(key=lambda x: x.get("started_at") or "")
        resp["model_runs"] = rr_runs
    return resp

def cancel_rewrite_request(api_key, rewrite_request_id, reason=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0457000" if __import__("os").path.isdir("./environment_mix/0457000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            t = s[:-1] if s.endswith("Z") else s
            return datetime.datetime.fromisoformat(t)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}".lower()

    def _rows_container(obj):
        # Accept either a list or {"rows":[...]}
        if isinstance(obj, list):
            return obj, None
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"], obj
        return [], None

    def _persist(filename, container, rows):
        if container is None:
            _save(filename, rows)
        else:
            container["rows"] = rows
            _save(filename, container)

    def _add_audit(audit_rows, event_type, api_key_id=None, rewrite_request_id=None, details=None):
        now = _now()
        audit_rows.append(
            {
                "id": _new_id("cpe_ae"),
                "event_type": event_type,
                "api_key_id": api_key_id,
                "rewrite_request_id": rewrite_request_id,
                "ip_address": None,
                "user_agent": None,
                "details": details,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
        )

    def _log_request_received(audit_rows, api_key_id, rewrite_request_id, call_status, extra=None):
        latency_ms = int(round((time.time() - t0) * 1000))
        _add_audit(
            audit_rows,
            "REQUEST_RECEIVED",
            api_key_id=api_key_id,
            rewrite_request_id=rewrite_request_id,
            details={
                "endpoint": "cancel_rewrite_request",
                "status": call_status,
                "latency_ms": latency_ms,
                **({} if extra is None else {"extra": extra}),
            },
        )

    # ---- validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(rewrite_request_id, str) or not rewrite_request_id.strip():
        return _err("VALIDATION_ERROR", "rewrite_request_id must be a non-empty string")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string or null")

    # ---- load stores
    api_obj = _load("api_keys.json")
    req_obj = _load("rewrite_requests.json")
    audit_obj = _load("audit_events.json")

    api_rows, api_container = _rows_container(api_obj)
    req_rows, req_container = _rows_container(req_obj)
    audit_rows, audit_container = _rows_container(audit_obj)

    # ---- authenticate: api_key parameter matches id OR stored client-visible value.
    # Note: stored key material is hashed; plaintext is not available. Do NOT compare to key_hash.
    key_row = None
    for r in api_rows:
        if isinstance(r, dict) and r.get("id") == api_key:
            key_row = r
            break
    if key_row is None:
        _log_request_received(audit_rows, None, rewrite_request_id, "unauthorized", extra={"reason": "api_key_not_found"})
        _persist("audit_events.json", audit_container, audit_rows)
        return _err("UNAUTHORIZED", "api_key was not recognized", api_key=api_key)

    api_key_id = key_row.get("id")

    # Allow administrative cancellation even if key is disabled/revoked; tool description says "accessible under caller's API key"
    # and audit defects indicate this should not be blocked by key status.
    # Still, if key is completely missing it's unauthorized (handled above).

    # ---- find request
    req_row = None
    for r in req_rows:
        if isinstance(r, dict) and r.get("id") == rewrite_request_id:
            req_row = r
            break
    if req_row is None:
        _log_request_received(audit_rows, api_key_id, rewrite_request_id, "not_found")
        _persist("audit_events.json", audit_container, audit_rows)
        return _err("NOT_FOUND", "rewrite_request_id not found", rewrite_request_id=rewrite_request_id)

    # ---- access control: if request is bound to an api_key_id, must match caller
    bound_key = req_row.get("api_key_id")
    if bound_key is not None and bound_key != api_key_id:
        _log_request_received(audit_rows, api_key_id, rewrite_request_id, "unauthorized", extra={"reason": "not_owner"})
        _persist("audit_events.json", audit_container, audit_rows)
        return _err(
            "UNAUTHORIZED",
            "rewrite request is not accessible under this api_key",
            api_key_id=api_key_id,
            rewrite_request_id=rewrite_request_id,
        )

    # ---- lifecycle transition validation
    cur = req_row.get("status")
    allowed = {"queued": {"running", "cancelled", "failed"}, "running": {"succeeded", "failed", "cancelled"}}
    if cur in ("succeeded", "failed", "cancelled"):
        _log_request_received(audit_rows, api_key_id, rewrite_request_id, "invalid_transition", extra={"from": cur, "to": "cancelled"})
        _persist("audit_events.json", audit_container, audit_rows)
        return _err(
            "INVALID_TRANSITION",
            "cannot cancel a terminal rewrite request; status is already terminal",
            rewrite_request_id=rewrite_request_id,
            status=cur,
        )
    if cur not in allowed or "cancelled" not in allowed[cur]:
        _log_request_received(audit_rows, api_key_id, rewrite_request_id, "invalid_transition", extra={"from": cur, "to": "cancelled"})
        _persist("audit_events.json", audit_container, audit_rows)
        return _err(
            "INVALID_TRANSITION",
            "cannot transition rewrite request to cancelled from current status",
            rewrite_request_id=rewrite_request_id,
            from_status=cur,
            to_status="cancelled",
        )

    # ---- mutate request
    now = _now()
    req_row["status"] = "cancelled"
    # terminalization timestamps
    if req_row.get("finished_at") is None:
        req_row["finished_at"] = _iso(now)
    # keep existing queued_at/started_at if present
    req_row["updated_at"] = _iso(now)
    # do not set error_code (cancel is not failure)
    req_row["error_code"] = None
    req_row["error_message"] = None

    # ---- audit event for cancellation
    _add_audit(
        audit_rows,
        "REQUEST_CANCELLED",
        api_key_id=api_key_id,
        rewrite_request_id=rewrite_request_id,
        details={"reason": reason} if reason is not None else None,
    )

    # ---- always log the call too
    _log_request_received(audit_rows, api_key_id, rewrite_request_id, "succeeded")

    # ---- persist
    _persist("rewrite_requests.json", req_container, req_rows)
    _persist("audit_events.json", audit_container, audit_rows)

    # ---- response envelope
    return {
        "rewrite_request": req_row,
        "cancelled": True,
    }

def list_rewrite_outputs(api_key, rewrite_request_id=None, status=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0457000" if __import__("os").path.isdir("./environment_mix/0457000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
