            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}".lower()

    def _add_audit(audit_rows, event_type, api_key_id=None, rewrite_request_id=None, details=None):
        now = _now()
        audit_rows.append({
            "id": _new_id("cpe_ae"),
            "event_type": event_type,
            "api_key_id": api_key_id,
            "rewrite_request_id": rewrite_request_id,
            "ip_address": None,
            "user_agent": None,
            "details": details,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })

    def _log_request_event(audit_rows, api_key_id, rewrite_request_id, status, latency_ms, details=None):
        _add_audit(
            audit_rows,
            "REQUEST_RECEIVED",
            api_key_id=api_key_id,
            rewrite_request_id=rewrite_request_id,
            details={
                "endpoint": "list_rewrite_outputs",
                "status": status,
                "latency_ms": latency_ms,
                **({} if details is None else {"extra": details}),
            },
        )

    # ---- validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if rewrite_request_id is not None and (not isinstance(rewrite_request_id, str) or not rewrite_request_id.strip()):
        return _err("VALIDATION_ERROR", "rewrite_request_id must be a non-empty string when provided")
    if status is not None and status not in ("generated", "redacted", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: generated, redacted, deleted")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int):
        return _err("VALIDATION_ERROR", "page_size must be an integer")
    if page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 200")
    if page_token is not None and (not isinstance(page_token, str) or not page_token.strip()):
        return _err("VALIDATION_ERROR", "page_token must be a non-empty string when provided")

    api_key = api_key.strip()
    if rewrite_request_id is not None:
        rewrite_request_id = rewrite_request_id.strip()
    if page_token is not None:
        page_token = page_token.strip()

    # ---- load
    api_keys = _load("api_keys.json")
    reqs = _load("rewrite_requests.json")
    outs = _load("rewrite_outputs.json")
    audit = _load("audit_events.json")

    # ---- authenticate (id or exact key_hash)
    key_row = None
    for r in api_keys if isinstance(api_keys, list) else []:
        if isinstance(r, dict) and (r.get("id") == api_key or r.get("key_hash") == api_key):
            key_row = r
            break
    if key_row is None:
        latency_ms = int((time.time() - _t0) * 1000)
        _log_request_event(audit, None, rewrite_request_id, "error", latency_ms, details={"error": "api_key_not_found"})
        _save("audit_events.json", audit)
        return _err("UNAUTHORIZED", "Invalid API key")

    api_key_id = key_row.get("id")
    # Reads are allowed for disabled keys; revoked is not.
    if key_row.get("status") == "revoked":
        latency_ms = int((time.time() - _t0) * 1000)
        _log_request_event(audit, api_key_id, rewrite_request_id, "error", latency_ms, details={"api_key_status": "revoked"})
        _save("audit_events.json", audit)
        return _err("UNAUTHORIZED", "API key is revoked", api_key_status="revoked")

    # ---- if scoping to a request, enforce accessibility and existence
    allowed_request_ids = None
    if rewrite_request_id is not None:
        req_row = None
        for r in reqs if isinstance(reqs, list) else []:
            if isinstance(r, dict) and r.get("id") == rewrite_request_id:
                req_row = r
                break
        if req_row is None:
            latency_ms = int((time.time() - _t0) * 1000)
            _log_request_event(audit, api_key_id, rewrite_request_id, "not_found", latency_ms)
            _save("audit_events.json", audit)
            return _err("NOT_FOUND", "rewrite request not found", rewrite_request_id=rewrite_request_id)

        owner_key_id = req_row.get("api_key_id")
        if owner_key_id is not None and owner_key_id != api_key_id:
            latency_ms = int((time.time() - _t0) * 1000)
            _log_request_event(audit, api_key_id, rewrite_request_id, "error", latency_ms, details={"rule": "ownership_mismatch"})
            _save("audit_events.json", audit)
            return _err("UNAUTHORIZED", "rewrite request is not accessible under this API key", rewrite_request_id=rewrite_request_id)

        allowed_request_ids = {rewrite_request_id}
    else:
        # Across requests: only include rows owned by this key OR public/internal (api_key_id null)
        allowed_request_ids = set()
        for r in reqs if isinstance(reqs, list) else []:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") in (None, api_key_id):
                rid = r.get("id")
                if isinstance(rid, str):
                    allowed_request_ids.add(rid)

    # ---- pagination
    # Vendor page_token in audit example is an id-like string; treat as "start after this output id" (stable by created_at then id).
    start_after_id = None
    if page_token:
        start_after_id = page_token

    # ---- filter
    filtered = []
    for o in outs if isinstance(outs, list) else []:
        if not isinstance(o, dict):
            continue
        rrid = o.get("rewrite_request_id")
        if rrid not in allowed_request_ids:
            continue
        if status is not None and o.get("status") != status:
            continue
        filtered.append(o)

    # ---- sort stable: created_at then id then variant_index
    def _sort_key(o):
        ca = o.get("created_at")
        # keep ISO lexicographic; fall back empty string
        return (ca if isinstance(ca, str) else "", o.get("id") if isinstance(o.get("id"), str) else "", o.get("variant_index") if isinstance(o.get("variant_index"), int) else -1)
    filtered.sort(key=_sort_key)

    # ---- apply start_after_id
    if start_after_id is not None:
        idx = 0
        found = False
        for i, o in enumerate(filtered):
            if o.get("id") == start_after_id:
                idx = i + 1
                found = True
                break
        # If token doesn't match, treat as starting at beginning (do not error; opaque token)
        if found:
            filtered = filtered[idx:]

    total = len(filtered)
    page = filtered[:page_size]
    has_more = total > len(page)
    next_cursor = page[-1].get("id") if has_more and page else None

    latency_ms = int((time.time() - _t0) * 1000)
    _log_request_event(
        audit,
        api_key_id,
        rewrite_request_id,
        "ok",
        latency_ms,
        details={"returned": len(page), "total_after_filters": total, "has_more": has_more},
    )
    _save("audit_events.json", audit)

    return {
        "data": page,
        "object": "list",
        "page_size": page_size,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "total": total,
    }

def update_rewrite_output_status(api_key, rewrite_output_id, status, redaction_reason=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0457000" if __import__("os").path.isdir("./environment_mix/0457000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}".lower()

    def _rows_container(obj):
        if isinstance(obj, list):
            return obj, None
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"], obj
        return [], None

    def _persist(filename, container, rows):
        if container is None:
            _save(filename, rows)
        else:
            container["rows"] = rows
            _save(filename, container)

    def _add_audit(audit_rows, event_type, api_key_id=None, rewrite_request_id=None, details=None):
        now = _now()
        audit_rows.append(
            {
                "id": _new_id("cpe_ae"),
                "event_type": event_type,
                "api_key_id": api_key_id,
                "rewrite_request_id": rewrite_request_id,
                "ip_address": None,
                "user_agent": None,
                "details": details,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
        )

    def _log_request_received(audit_rows, api_key_id, rewrite_request_id, call_status, extra=None):
        latency_ms = int(round((time.time() - t0) * 1000))
        _add_audit(
            audit_rows,
            "REQUEST_RECEIVED",
            api_key_id=api_key_id,
            rewrite_request_id=rewrite_request_id,
            details={
                "endpoint": "update_rewrite_output_status",
                "status": call_status,
                "latency_ms": latency_ms,
                **({} if extra is None else {"extra": extra}),
            },
        )

    # ---- validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(rewrite_output_id, str) or not rewrite_output_id.strip():
        return _err("VALIDATION_ERROR", "rewrite_output_id must be a non-empty string")
    if status not in ("redacted", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: redacted, deleted")
    if redaction_reason is not None and not isinstance(redaction_reason, str):
        return _err("VALIDATION_ERROR", "redaction_reason must be a string or null")
    if status == "redacted" and redaction_reason is not None and len(redaction_reason) > 2000:
        return _err("VALIDATION_ERROR", "redaction_reason is too long (max 2000 characters)")

    # ---- load stores
    api_obj = _load("api_keys.json")
    out_obj = _load("rewrite_outputs.json")
    req_obj = _load("rewrite_requests.json")
    audit_obj = _load("audit_events.json")

    api_rows, api_container = _rows_container(api_obj)
    out_rows, out_container = _rows_container(out_obj)
    req_rows, req_container = _rows_container(req_obj)
    audit_rows, audit_container = _rows_container(audit_obj)

    # ---- authenticate: match id only (never compare against key_hash)
    key_row = None
    for r in api_rows:
        if isinstance(r, dict) and r.get("id") == api_key:
            key_row = r
            break
    if key_row is None:
        _log_request_received(audit_rows, None, None, "unauthorized", extra={"reason": "api_key_not_found"})
        _persist("audit_events.json", audit_container, audit_rows)
        return _err("UNAUTHORIZED", "api_key was not recognized", api_key=api_key)

    api_key_id = key_row.get("id")

    # ---- locate output
    out_row = None
    for r in out_rows:
        if isinstance(r, dict) and r.get("id") == rewrite_output_id:
            out_row = r
            break
    if out_row is None:
        _log_request_received(audit_rows, api_key_id, None, "not_found")
        _persist("audit_events.json", audit_container, audit_rows)
        return _err("NOT_FOUND", "rewrite_output_id not found", rewrite_output_id=rewrite_output_id)

    # ---- validate referenced rewrite request exists
    rrid = out_row.get("rewrite_request_id")
    req_row = None
    if rrid is not None:
        for r in req_rows:
            if isinstance(r, dict) and r.get("id") == rrid:
                req_row = r
                break
    if req_row is None:
        _log_request_received(audit_rows, api_key_id, rrid, "not_found", extra={"reason": "orphan_output"})
        _persist("audit_events.json", audit_container, audit_rows)
        return _err(
            "NOT_FOUND",
            "rewrite request referenced by output does not exist",
            rewrite_output_id=rewrite_output_id,
            rewrite_request_id=rrid,
        )

    # ---- access control: if rewrite request is bound to api_key_id, must match caller
    bound_key = req_row.get("api_key_id")
    if bound_key is not None and bound_key != api_key_id:
        _log_request_received(audit_rows, api_key_id, rrid, "unauthorized", extra={"reason": "not_owner"})
        _persist("audit_events.json", audit_container, audit_rows)
        return _err(
            "UNAUTHORIZED",
            "rewrite output is not accessible under this api_key",
            api_key_id=api_key_id,
            rewrite_output_id=rewrite_output_id,
        )

    # ---- lifecycle transitions for rewrite_outputs
    cur = out_row.get("status")
    transitions = {"generated": {"redacted", "deleted"}, "redacted": {"deleted"}, "deleted": set()}
    if cur not in transitions:
        _log_request_received(audit_rows, api_key_id, rrid, "validation_error", extra={"bad_current_status": cur})
        _persist("audit_events.json", audit_container, audit_rows)
        return _err("VALIDATION_ERROR", "rewrite output has invalid stored status", rewrite_output_id=rewrite_output_id, status=cur)

    if cur == "deleted":
        _log_request_received(audit_rows, api_key_id, rrid, "invalid_transition", extra={"from": cur, "to": status})
        _persist("audit_events.json", audit_container, audit_rows)
        return _err("INVALID_TRANSITION", "cannot modify a deleted output", rewrite_output_id=rewrite_output_id)

    if status not in transitions[cur]:
        _log_request_received(audit_rows, api_key_id, rrid, "invalid_transition", extra={"from": cur, "to": status})
        _persist("audit_events.json", audit_container, audit_rows)
        return _err(
            "INVALID_TRANSITION",
            "invalid rewrite output status transition",
            rewrite_output_id=rewrite_output_id,
            from_status=cur,
            to_status=status,
        )

    # ---- mutate output
    now = _now()
    out_row["status"] = status
    out_row["updated_at"] = _iso(now)
    if status == "redacted":
        # store reason in structured_sections to avoid schema changes; keep existing sections if present
        ss = out_row.get("structured_sections")
        if ss is None or not isinstance(ss, dict):
            ss = {}
        if redaction_reason is not None:
            ss["redaction_reason"] = redaction_reason
        ss["redacted_at"] = _iso(now)
        out_row["structured_sections"] = ss
        # redact content
        out_row["rewritten_prompt"] = "[REDACTED]"
    elif status == "deleted":
        # delete content (retain row for uniqueness/audit)
        out_row["rewritten_prompt"] = ""
        ss = out_row.get("structured_sections")
        if ss is None or not isinstance(ss, dict):
            ss = {}
        ss["deleted_at"] = _iso(now)
        out_row["structured_sections"] = ss

    # ---- audit: emit an event tied to the request (closest available types)
    if status == "redacted":
        _add_audit(
            audit_rows,
            "REQUEST_FAILED" if req_row.get("status") == "failed" else "REQUEST_CANCELLED" if req_row.get("status") == "cancelled" else "REQUEST_SUCCEEDED",
            api_key_id=api_key_id,
            rewrite_request_id=rrid,
            details={"output_id": rewrite_output_id, "output_status": "redacted", **({} if redaction_reason is None else {"redaction_reason": redaction_reason})},
        )
    else:
        _add_audit(
            audit_rows,
            "REQUEST_FAILED" if req_row.get("status") == "failed" else "REQUEST_CANCELLED" if req_row.get("status") == "cancelled" else "REQUEST_SUCCEEDED",
            api_key_id=api_key_id,
            rewrite_request_id=rrid,
            details={"output_id": rewrite_output_id, "output_status": "deleted"},
        )

    _log_request_received(audit_rows, api_key_id, rrid, "succeeded")

    # ---- persist
    _persist("rewrite_outputs.json", out_container, out_rows)
    _persist("audit_events.json", audit_container, audit_rows)

    return {
        "rewrite_output": out_row,
    }
